 "content": "def transform(grid):
    """Extend pairs of same-color markers along rows/columns of an 8-grid."""
    h, w = len(grid), len(grid[0])
    row_bars = [r for r in range(h) if all(v == 8 for v in grid[r])]
    col_bars = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def bands(size, bars):
        starts = [0] + [b + 1 for b in bars]
        ends = bars + [size]
        spans = [(s, e) for s, e in zip(starts, ends) if e > s]
        # A final incomplete margin beyond the last full cell is not a grid cell.
        lengths = [e - s for s, e in spans]
        full = max(set(lengths), key=lengths.count)
        return [(s, e) for s, e in spans if e - s == full]

    rb = bands(h, row_bars)
    cb = bands(w, col_bars)
    out = [row[:] for row in grid]
    markers = {}
    for ri, (r0, r1) in enumerate(rb):
        for ci, (c0, c1) in enumerate(cb):
            colors = {grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] not in (0, 8)}
            for color in colors:
                markers.setdefault(color, []).append((ri, ci))

    paint = {}
    for color, points in markers.items():
        if len(points) < 2:
            continue
        # Each pair defines a straight segment in cell coordinates.
        for i in range(len(points)):
            for j in range(i + 1, len(points)):
                r0, c0 = points[i]
                r1, c1 = points[j]
                if r0 == r1:
                    cells = [(r0, c) for c in range(min(c0, c1), max(c0, c1) + 1)]
                elif c0 == c1:
                    cells = [(r, c0) for r in range(min(r0, r1), max(r0, r1) + 1)]
                else:
                    continue
                for cell in cells:
                    paint.setdefault(cell, set()).add(color)

    for (ri, ci), colors in paint.items():
        color = 6 if 2 in colors and 3 in colors else min(colors)
        r0, r1 = rb[ri]
        c0, c1 = cb[ci]
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = color
    return out
